import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 93 A noble gift","description":"学习 定语从句与指代，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 93 A noble gift","description":"学习 定语从句与指代，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 定语从句与指代，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 92 Asking for trouble","link":"/life/english/new-concept/book-2/unit-04/lesson-092"},"next":{"text":"第二册：实践与进步 · Lesson 94 Future champions","link":"/life/english/new-concept/book-2/unit-04/lesson-094"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 92 Asking for trouble","link":"/life/english/new-concept/book-2/unit-04/lesson-092"},"next":{"text":"第二册：实践与进步 · Lesson 94 Future champions","link":"/life/english/new-concept/book-2/unit-04/lesson-094"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-093.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-093.md"}'),i={name:"life/english/new-concept/book-2/unit-04/lesson-093.md"};function s(l,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-93-a-noble-gift" tabindex="-1">第二册：实践与进步 · Lesson 93 A noble gift <a class="header-anchor" href="#第二册-实践与进步-·-lesson-93-a-noble-gift" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 93 A noble gift&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>大型纪念礼物从制作到运送需多人合作，介绍时应交代受赠者与象征意义；练习被动定语。本课的语言观察是：which was donated ... 补充物品来源，若用逗号是非限制性说明；主句仍需独立谓语 stands。不能把整个句子停在 which 从句结束处。完成学习后，请为一件虚构公共礼物写介绍，交代来源、所在位置和象征意义。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>gift</td><td>/ɡɪft/</td><td>n.</td><td>礼物</td><td>a generous gift</td></tr><tr><td>statue</td><td>/ˈstætʃuː/</td><td>n.</td><td>雕像</td><td>a bronze statue</td></tr><tr><td>donate</td><td>/dəʊˈneɪt/</td><td>v.</td><td>捐赠</td><td>donate money</td></tr><tr><td>symbol</td><td>/ˈsɪmbəl/</td><td>n.</td><td>象征</td><td>a symbol of friendship</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>a gift from — 来自……的礼物</li><li>a symbol of — ……的象征，不等于实际包含该事物</li></ul><h2 id="语法讲解-定语从句与指代" tabindex="-1">语法讲解：定语从句与指代 <a class="header-anchor" href="#语法讲解-定语从句与指代" aria-label="Permalink to &quot;语法讲解：定语从句与指代&quot;">​</a></h2><p>定语从句跟在被修饰名词之后，用 who、which、that 等连接并在从句内承担成分。限制性从句帮助确定“是哪一个”，非限制性从句用逗号补充信息。关系代词作宾语时，在限制性从句中常可省略；作主语时不能省略。先确定先行词，再检查从句缺主语、宾语还是状语，避免同时保留一个多余的 he、it 或 them。本课应用：which was donated ... 补充物品来源，若用逗号是非限制性说明；主句仍需独立谓语 stands。不能把整个句子停在 which 从句结束处。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The statue, which was donated by local artists, stands beside the library.</p></blockquote><p>这座由当地艺术家捐赠的雕像立在图书馆旁。</p><p>The statue 为主语，stands 为主句谓语；逗号内 which was donated 是非限制性定语从句，which 指 statue。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>非限制性从句通常不能用 that 替代 which，也不能省略关系代词。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在两逗号处短停，保持主干 The statue stands 清晰，donated 的 -ed 读 /ɪd/。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The statue, which was donated by local artists, stands beside the library. Students designed the garden around it. A plaque explains the donors&#39; wish for friendship.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为一件虚构公共礼物写介绍，交代来源、所在位置和象征意义。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：The statue 为主语，stands 为主句谓语；逗号内 which was donated 是非限制性定语从句，which 指 statue。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：非限制性从句通常不能用 that 替代 which，也不能省略关系代词。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 which/that：The statue, ___ was donated last year, stands here.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> which</p><p><strong>解析：</strong> 逗号引出的非限制性从句用 which。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>谁设计了周围的花园？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Students.</p><p><strong>解析：</strong> 艺术家捐雕像，学生设计花园，角色不同。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>句子主句谓语是 was donated 还是 stands？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> stands</p><p><strong>解析：</strong> was donated 位于插入的定语从句内。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：定语从句与指代。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-092">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-094">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",s]]);export{p as __pageData,b as default};
